package com.mohymods.kingdomsmp.profession;
import com.mohymods.kingdomsmp.placement.PlacementProtection;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.Container;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
/** Sparse current-route inspection: no chunk tickets, copied client counts or inventory consumption. */
public final class MineInspection {
 public static final String LIGHTING="kingdom_smp:miner/a06",FINAL="kingdom_smp:miner/a08";
 private static final Set<Block> LIGHTS=Set.of(Blocks.TORCH,Blocks.WALL_TORCH,Blocks.SOUL_TORCH,Blocks.SOUL_WALL_TORCH,Blocks.LANTERN,Blocks.SOUL_LANTERN,Blocks.GLOWSTONE,Blocks.SEA_LANTERN,Blocks.JACK_O_LANTERN);
 private MineInspection(){}
 public static boolean contains(String id){return LIGHTING.equals(id)||FINAL.equals(id);}
 static String group(String item){return switch(item){case "minecraft:coal"->"coal";case "minecraft:raw_iron","minecraft:iron_ore","minecraft:deepslate_iron_ore"->"iron";case "minecraft:raw_copper","minecraft:copper_ore","minecraft:deepslate_copper_ore"->"copper";default->null;};}
 public static String validate(ServerPlayer p,String id,BlockPos center){String path=MineAccessService.validate(p);var route=MineAccessSavedData.get(p.server).evidence().route(p.getUUID()).orElseThrow();var entry=BlockPos.of(route.cells().getFirst());if(Math.abs((long)entry.getX()-center.getX())>8||Math.abs((long)entry.getY()-center.getY())>4||Math.abs((long)entry.getZ()-center.getZ())>8)throw new IllegalStateException("Center the mine inspection on the actual recorded route entrance");var level=p.serverLevel();var facts=new TreeMap<String,String>();Set<Long> lamps=new HashSet<>();
  for(long cell:route.cells()){var base=BlockPos.of(cell);for(var cursor:BlockPos.betweenClosed(base.offset(-2,1,-2),base.offset(2,3,2))){var pos=cursor.immutable();if(!level.hasChunkAt(pos))throw new IllegalStateException("Visit the full route and lighting first; inspection never loads chunks");var state=level.getBlockState(pos);if(!LIGHTS.contains(state.getBlock())||state.getLightEmission(level,pos)<=0||!state.canSurvive(level,pos))continue;if(!level.getWorldBorder().isWithinBounds(pos)||PlacementProtection.check(level,p,pos,pos)!=null)throw new IllegalStateException("Current mine light permission is unavailable at "+pos.toShortString());lamps.add(pos.asLong());facts.put("lamp:"+pos.asLong(),state.toString());}}
  int required=MineAccessRules.get(p.server).lights();if(lamps.size()<required)throw new IllegalStateException("Maintain "+required+" distinct actual supported lights along the retained route: "+lamps.size()+" present");
  if(FINAL.equals(id)){boolean tool=false;for(int i=0;i<36;i++){var stack=p.getInventory().getItem(i);if(Set.of(Items.STONE_PICKAXE,Items.IRON_PICKAXE,Items.DIAMOND_PICKAXE,Items.NETHERITE_PICKAXE).contains(stack.getItem())&&(!stack.isDamageableItem()||stack.getDamageValue()<stack.getMaxDamage())){tool=true;facts.put("tool:"+i,stack.getItem()+":"+stack.getDamageValue());}}if(!tool)throw new IllegalStateException("Bring a functional ordinary mining pickaxe to demonstrate equipment");Set<String> sorted=new HashSet<>();int bins=0;
   for(var cursor:BlockPos.betweenClosed(entry.offset(-8,-3,-8),entry.offset(8,3,8))){var pos=cursor.immutable();if(!level.hasChunkAt(pos))throw new IllegalStateException("Visit the sorting workspace before inspection");var state=level.getBlockState(pos);if(!(state.is(Blocks.BARREL)||state.is(Blocks.CHEST))||!(level.getBlockEntity(pos) instanceof Container container))continue;if(PlacementProtection.check(level,p,pos,pos)!=null)throw new IllegalStateException("Sorting storage permission changed");boolean access=false;for(var direction:Direction.Plane.HORIZONTAL){var foot=pos.relative(direction);if(!level.getBlockState(foot).getCollisionShape(level,foot).isEmpty()||!level.getBlockState(foot.above()).getCollisionShape(level,foot.above()).isEmpty()||!level.getBlockState(foot.below()).isFaceSturdy(level,foot.below(),Direction.UP))continue;access=true;}if(!access)continue;Set<String> groups=new HashSet<>();var content=new StringBuilder();for(int slot=0;slot<Math.min(container.getContainerSize(),128);slot++){var stack=container.getItem(slot);if(stack.isEmpty())continue;String item=BuiltInRegistries.ITEM.getKey(stack.getItem()).toString(),kind=group(item);if(kind!=null)groups.add(kind);content.append(slot).append('=').append(item).append(':').append(stack.getCount()).append(':').append(stack.getComponents().hashCode()).append(';');}if(groups.size()==1){bins++;sorted.addAll(groups);facts.put("bin:"+pos.asLong(),content.toString());}}
   if(bins<2||sorted.size()<2)throw new IllegalStateException("Maintain at least two accessible separately stocked coal/iron/copper sorting bins near the entrance; mixed unsorted containers do not qualify");}
  facts.put("route",path);try{return "mine="+java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(facts.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)),0,16)+",lights="+lamps.size();}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}
 }
}
